        let t7 = t0 + t1;
        let t8 = (-v[1]).mul_add(v[2], t2);
        let t9 = t0 - t1;
        let t10 = v[0].mul_add(v[2], t6);
        let t11 = xv[0] * t7;
        let t12 = xv[1] * t7;
        let t15 = xv[3] * t4;
        let t16 = xv[1] * t10;
        let t19 = (-xv[1]).mul_add(t8, t15);
        let t20 = t19 * T::from_i64(2);
        let t21 = xv[2].mul_add(t9, t20);
