        let m1 = v[0] * v[1];
        let m2 = v[1] * v[1];
        let m4 = v[1] * v[2];
        let m6 = v[1] * v[3];
        let m7 = m0 - m2;
        let m8 = m1 * T::from_i64(2);
        let m9 = -m8;
